export const INSTANCE_STRIDE_BYTES = 28
export const INSTANCE_STRIDE_WORDS = 7

// Word indices into a Float32Array view over the instance buffer.
export const INSTANCE_OFFSET_F32 = {
  y: 3,
  size: 4,
} as const

// Word indices into a Uint32Array view over the instance buffer.
export const INSTANCE_OFFSET_U32 = {
  x: 0,
  x2: 1,
  x2Region: 2,
  color: 5,
  row: 6,
} as const

export const VERTEX_ATTRIBUTES: readonly VertexAttributeLayout[] = [
  { name: 'a_x', components: 1, type: 'uint', offsetBytes: 0, integer: true },
  { name: 'a_x2', components: 1, type: 'uint', offsetBytes: 4, integer: true },
  { name: 'a_x2Region', components: 1, type: 'uint', offsetBytes: 8, integer: true },
  { name: 'a_y', components: 1, type: 'float', offsetBytes: 12, integer: false },
  { name: 'a_size', components: 1, type: 'float', offsetBytes: 16, integer: false },
  { name: 'a_color', components: 1, type: 'uint', offsetBytes: 20, integer: true },
  { name: 'a_row', components: 1, type: 'uint', offsetBytes: 24, integer: true },
]

export interface InstanceArrays {
  x: ArrayLike<number>
  x2: ArrayLike<number>
  x2Region: ArrayLike<number>
  y: ArrayLike<number>
  size: ArrayLike<number>
  color: ArrayLike<number>
  row: ArrayLike<number>
}

export function packInstances(
  arrays: InstanceArrays,
  numInstances: number,
  buf: ArrayBuffer = new ArrayBuffer(numInstances * INSTANCE_STRIDE_BYTES),
) {
  const f32 = new Float32Array(buf)
  const u32 = new Uint32Array(buf)
  const { x, x2, x2Region, y, size, color, row } = arrays
  for (let i = 0; i < numInstances; i++) {
    const o = i * INSTANCE_STRIDE_WORDS
    u32[o + 0] = x[i]!
    u32[o + 1] = x2[i]!
    u32[o + 2] = x2Region[i]!
    f32[o + 3] = y[i]!
    f32[o + 4] = size[i]!
    u32[o + 5] = color[i]!
    u32[o + 6] = row[i]!
  }
  return buf
}

// Instance `i`'s `x`.
export function getInstanceX(u32: Uint32Array, i: number) {
  return u32[i * INSTANCE_STRIDE_WORDS]!
}

export function setInstanceX(u32: Uint32Array, i: number, v: number) {
  u32[i * INSTANCE_STRIDE_WORDS] = v
}

// Instance `i`'s `x2`.
export function getInstanceX2(u32: Uint32Array, i: number) {
  return u32[i * INSTANCE_STRIDE_WORDS + 1]!
}

export function setInstanceX2(u32: Uint32Array, i: number, v: number) {
  u32[i * INSTANCE_STRIDE_WORDS + 1] = v
}

// Instance `i`'s `x2Region`.
export function getInstanceX2Region(u32: Uint32Array, i: number) {
  return u32[i * INSTANCE_STRIDE_WORDS + 2]!
}

export function setInstanceX2Region(u32: Uint32Array, i: number, v: number) {
  u32[i * INSTANCE_STRIDE_WORDS + 2] = v
}

// Instance `i`'s `y`.
export function getInstanceY(f32: Float32Array, i: number) {
  return f32[i * INSTANCE_STRIDE_WORDS + 3]!
}

export function setInstanceY(f32: Float32Array, i: number, v: number) {
  f32[i * INSTANCE_STRIDE_WORDS + 3] = v
}

// Instance `i`'s `size`.
export function getInstanceSize(f32: Float32Array, i: number) {
  return f32[i * INSTANCE_STRIDE_WORDS + 4]!
}

export function setInstanceSize(f32: Float32Array, i: number, v: number) {
  f32[i * INSTANCE_STRIDE_WORDS + 4] = v
}

// Instance `i`'s `color`.
export function getInstanceColor(u32: Uint32Array, i: number) {
  return u32[i * INSTANCE_STRIDE_WORDS + 5]!
}

export function setInstanceColor(u32: Uint32Array, i: number, v: number) {
  u32[i * INSTANCE_STRIDE_WORDS + 5] = v
}

// Instance `i`'s `row`.
export function getInstanceRow(u32: Uint32Array, i: number) {
  return u32[i * INSTANCE_STRIDE_WORDS + 6]!
}

export function setInstanceRow(u32: Uint32Array, i: number, v: number) {
  u32[i * INSTANCE_STRIDE_WORDS + 6] = v
}

// Combined `Sampler2D` bindings. Texture unit indices start at 0.
export const TEXTURES: readonly [TextureBinding, ...TextureBinding[]] = [
  { glTextureUnit: 0, glUniformName: 'u_colorRamp', filter: 'linear' },
]
